// Calculate date range for "past week"
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const formatISO = (d) => d.toISOString();

return [{
  since: formatISO(weekAgo),
  until: formatISO(now),
  sinceShort: weekAgo.toISOString().split('T')[0],
  untilShort: now.toISOString().split('T')[0],
  repoOwner: $env.REPO_OWNER || 'your-org',
  repoName: $env.REPO_NAME || 'your-repo'
}];

// Combine and transform all GitHub data into a clean payload for Claude

const commits = $input.first().json;  // from Get Commits node
const issues = $input.all()[1].json;  // from Get Issues node
const prs = $input.all()[2].json;     // from Get PRs node

// Handle both array and single-object responses
const commitList = Array.isArray(commits) ? commits : (commits.data || []);
const issueList = Array.isArray(issues) ? issues : (issues.data || []);
const prList = Array.isArray(prs) ? prs : (prs.data || []);

// Filter only actually merged PRs
const mergedPRs = prList.filter(p => p.merged_at !== null && p.merged_at !== undefined);

// Filter out pull requests from issues (GitHub API includes PRs in issue results)
const actualIssues = issueList.filter(i => !i.pull_request);

// Extract commit summaries (shorten messages)
const commitSummaries = commitList.map(c => ({
  sha: c.sha ? c.sha.substring(0, 7) : 'unknown',
  message: (c.commit?.message || '').split('\n')[0],
  author: c.commit?.author?.name || c.author?.login || 'unknown',
  date: c.commit?.author?.date || c.commit?.committer?.date || ''
}));

// Extract issue summaries
const issueSummaries = actualIssues.map(i => ({
  number: i.number,
  title: i.title,
  state: i.state,
  author: i.user?.login || 'unknown',
  labels: (i.labels || []).map(l => l.name),
  url: i.html_url
}));

// Extract merged PR summaries
const prSummaries = mergedPRs.map(p => ({
  number: p.number,
  title: p.title,
  author: p.user?.login || 'unknown',
  merged_by: p.merged_by?.login || 'unknown',
  labels: (p.labels || []).map(l => l.name),
  url: p.html_url,
  additions: p.additions || 0,
  deletions: p.deletions || 0
}));

return [{
  repoOwner: $('Calculate Date Range').item.json.repoOwner,
  repoName: $('Calculate Date Range').item.json.repoName,
  since: $('Calculate Date Range').item.json.sinceShort,
  until: $('Calculate Date Range').item.json.untilShort,
  stats: {
    total_commits: commitSummaries.length,
    total_closed_issues: actualIssues.length,
    total_merged_prs: prSummaries.length,
    total_authors: [...new Set(commitSummaries.map(c => c.author))].length
  },
  commit_summaries: commitSummaries,
  issue_summaries: issueSummaries,
  pr_summaries: prSummaries
}];

