// Extract the report content from Claude's response
const response = $input.first().json;

// Claude API response structure (Messages API)
let reportContent = '';

if (response.content && Array.isArray(response.content)) {
  reportContent = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else if (typeof response === 'string') {
  reportContent = response;
} else {
  reportContent = JSON.stringify(response, null, 2);
}

const repoOwner = $('Transform GitHub Data').item.json.repoOwner;
const repoName = $('Transform GitHub Data').item.json.repoName;
const since = $('Transform GitHub Data').item.json.since;
const until = $('Transform GitHub Data').item.json.until;

return [{
  report: reportContent,
  repoOwner: repoOwner,
  repoName: repoName,
  weekRange: `${since} ~ ${until}`,
  filename: `weekly-report-${repoOwner}-${repoName}-${until}.md`,
  markdown: `# Weekly Report: ${repoOwner}/${repoName}\n\n**Period:** ${since} ~ ${until}\n\n---\n\n${reportContent}`
}];

// Option A: Print to n8n console for review
const report = $input.first().json;
console.log('=== WEEKLY REPORT GENERATED ===');
console.log(`Repository: ${report.repoOwner}/${report.repoName}`);
console.log(`Period: ${report.weekRange}`);
console.log(report.markdown);

return [$input.first().json];

// Option B: Save report as a file through n8n's file system
// You can use this node in combination with "Write Binary File" or a file-write approach
// For now, just pass through - the report is in $json.markdown
return [$input.first().json];
